import kotlin.math.floor

fun put(band: CharArray, position: Double, symbol: Char) { band[minOf(60.0, maxOf(0.0, position)).toInt()] = symbol }
fun variableBand(limits: Limits, value: Double, signalled: Boolean): String {
    val band = CharArray(61) { '.' }
    fun position(v: Double) = floor(60.0 * ((v - limits.lcl) / (limits.ucl - limits.lcl)) + 0.5)
    put(band, 0.0, ':'); put(band, 60.0, ':'); put(band, position(limits.cl), '|'); put(band, position(value), if (signalled) '*' else 'o')
    return band.concatToString()
}
fun cusumBand(upper: Double, lower: Double, threshold: Double, highSignal: Boolean, lowSignal: Boolean): String {
    val band = CharArray(61) { '.' }
    put(band, 0.0, ':'); put(band, 60.0, ':'); put(band, 30.0, '|')
    if (lower > 0.0) put(band, 30.0 - minOf(30.0, floor(30.0 * (lower / threshold) + 0.5)), if (lowSignal) '*' else '-')
    if (upper > 0.0) put(band, 30.0 + minOf(30.0, floor(30.0 * (upper / threshold) + 0.5)), if (highSignal) '*' else '+')
    return band.concatToString()
}
fun smoothBand(width: Double, rowWidth: Double, value: Double, center: Double, signalled: Boolean): String {
    val band = CharArray(61) { '.' }
    val edge = minOf(30.0, floor(30.0 * (rowWidth / width) + 0.5))
    put(band, 30.0, '|'); put(band, 30.0 - edge, ':'); put(band, 30.0 + edge, ':')
    put(band, 30.0 + floor(30.0 * ((value - center) / width) + 0.5), if (signalled) '*' else 'o')
    return band.concatToString()
}
fun standardBand(z: Double, okay: Boolean): String {
    val band = CharArray(61) { '.' }
    put(band, 0.0, ':'); put(band, 60.0, ':'); put(band, 30.0, '|'); put(band, 30.0 + floor(10.0 * z + 0.5), if (okay) 'o' else '*')
    return band.concatToString()
}

data class Point(val number: Int, val value: Double)
data class Signal(val chart: String, val rule: String, val start: Int, val end: Int, val value: Double, val direction: String) {
    fun subgroup(size: Int) = if (chart == "I" || chart == "MR") (end - 1) / size + 1 else end
}
data class Zones(val upper1: Double, val upper2: Double, val lower1: Double, val lower2: Double)
fun zones(limits: Limits): Zones {
    val above = (limits.ucl - limits.cl) / 3.0
    val below = (limits.cl - limits.lcl) / 3.0
    return Zones(limits.cl + above, limits.cl + 2.0 * above, limits.cl - below, limits.cl - 2.0 * below)
}
fun zoneName(value: Double, limits: Limits): String {
    val zone = zones(limits)
    return when { value > limits.ucl -> "OUT+"; value < limits.lcl -> "OUT-"; value > zone.upper2 -> "A+"; value > zone.upper1 -> "B+"; value > limits.cl -> "C+"; value < zone.lower2 -> "A-"; value < zone.lower1 -> "B-"; value < limits.cl -> "C-"; else -> "C0" }
}

fun runRules(chart: String, points: List<Point>, limits: Limits, rules: List<Int>): List<Signal> {
    val lengths = listOf(0, 1, 3, 5, 8, 6, 14, 15, 8)
    val zone = zones(limits)
    val signals = mutableListOf<Signal>()
    for (index in points.indices) for (rule in rules) {
        val length = lengths[rule]
        if (index + 1 < length) continue
        val window = points.subList(index + 1 - length, index + 1).map { it.value }
        val value = window.last()
        val direction = when (rule) {
            1 -> if (limits.outside(value)) if (value > limits.cl) "UP" else "DOWN" else null
            2 -> when { value > zone.upper2 && window.count { it > zone.upper2 } >= 2 -> "UP"; value < zone.lower2 && window.count { it < zone.lower2 } >= 2 -> "DOWN"; else -> null }
            3 -> when { value > zone.upper1 && window.count { it > zone.upper1 } >= 4 -> "UP"; value < zone.lower1 && window.count { it < zone.lower1 } >= 4 -> "DOWN"; else -> null }
            4 -> when { window.all { it > limits.cl } -> "UP"; window.all { it < limits.cl } -> "DOWN"; else -> null }
            5 -> when { window.zipWithNext().all { (a, b) -> b > a } -> "UP"; window.zipWithNext().all { (a, b) -> b < a } -> "DOWN"; else -> null }
            6 -> { val differences = window.zipWithNext { a, b -> b - a }; if (differences.all { it != 0.0 } && differences.zipWithNext().all { (a, b) -> (a > 0.0) != (b > 0.0) }) "NONE" else null }
            7 -> if (window.all { it > zone.lower1 && it < zone.upper1 }) "NONE" else null
            else -> if (window.all { it > zone.upper1 || it < zone.lower1 } && window.any { it > zone.upper1 } && window.any { it < zone.lower1 }) "NONE" else null
        }
        if (direction != null) signals += Signal(chart, rule.toString(), points[index + 1 - length].number, points[index].number, value, direction)
    }
    return signals
}

import kotlin.math.abs
import kotlin.math.sqrt

data class Subgroup(val number: Int, val values: List<Long>) {
    val total = values.sum()
    val squares = values.sumOf { it * it }
    val mean = total.toDouble() / values.size.toDouble()
    val range = values.max() - values.min()
    val sd = sqrt((values.size.toLong() * squares - total * total).toDouble() / (values.size.toLong() * (values.size - 1).toLong()).toDouble())
}
data class Limits(val lcl: Double, val cl: Double, val ucl: Double) { fun outside(value: Double) = value > ucl || value < lcl }
data class FamilyLimits(val first: Limits, val second: Limits)
fun realSum(values: Iterable<Double>): Double { var total = 0.0; for (value in values) total += value; return total }

fun familyLimits(family: String, ids: List<Int>, groups: List<Subgroup>, samples: List<Long>, size: Int, constants: ControlConstants): FamilyLimits {
    if (family == "I_MR") {
        val values = ids.map { samples[it - 1] }
        val mean = values.sum().toDouble() / values.size.toDouble()
        val ranges = values.zipWithNext { first, second -> abs(second - first) }
        val moving = ranges.sum().toDouble() / ranges.size.toDouble()
        val pair = controlConstants(2)
        return FamilyLimits(Limits(mean - 3.0 * moving / pair.d2, mean, mean + 3.0 * moving / pair.d2), Limits(pair.d3 * moving, moving, pair.d4 * moving))
    }
    val selected = ids.map { groups[it - 1] }
    val mean = selected.sumOf { it.total }.toDouble() / (ids.size * size).toDouble()
    if (family == "XBAR_R") {
        val range = selected.sumOf { it.range }.toDouble() / selected.size.toDouble()
        return FamilyLimits(Limits(mean - constants.a2 * range, mean, mean + constants.a2 * range), Limits(constants.d3 * range, range, constants.d4 * range))
    }
    val sd = realSum(selected.map { it.sd }) / selected.size.toDouble()
    return FamilyLimits(Limits(mean - constants.a3 * sd, mean, mean + constants.a3 * sd), Limits(constants.b3 * sd, sd, constants.b4 * sd))
}
